const state = {csrf:'',revision:0,projects:[],orchestras:[],selected_projects:[],selected_providers:[],roots:[],defaults:{},project_overrides:{},providers:[],catalogs:{},jobs:[],page:'projects',busy:false,onboard:false,onboardStep:1,usage:null};
const clone = value => JSON.parse(JSON.stringify(value));
