const roleDescription = role => roles[role]?.[lang==='tr'?2:3] || t('roleUnknown');
const node = (tag, className='', content) => {const element=document.createElement(tag);if(className)element.className=className;if(content!==undefined)element.textContent=String(content);return element;};
const button = (label, action, kind='', disabled=false, icon) => {const b=node('button','button '+kind,label);if(icon)b.prepend(uiIcon(icon));b.type='button';b.disabled=disabled;b.addEventListener('click',action);return b;};
const field = (label,input,wide=false) => {const holder=node('label','field'+(wide?' wide':''));const caption=node('span','',label);caption.id='field-'+crypto.randomUUID();input.setAttribute('aria-labelledby',caption.id);holder.append(caption,input);return holder;};
