  state.usageProject=project.value;state.usageProvider=provider.value;if(!project.value)return notify('selectProjects','error');if(!hasUsageRecords(provider.value))return notify('usageUnsupported');if(!dateRange)return showError(Error(t('usageInvalidDates')));
