function readySuitability(profile,provider){if(provider==='opencode')return t('readyOpenCode');const keys={balanced:'readyBalanced',quality:'readyQuality',economy:'readyEconomy','quota-saver':'readyQuota',focused:'readyFocused'};return t(keys[profile]||'readyGeneric');}
