 const draft=blankOrchestra(provider);draft.id=crypto.randomUUID();draft.task_type=taskType;draft.name=t('taskTeamName',{task:taskLabels[lang][taskType],profile:profileLabel(profile),provider:providerNames[provider]});draft.profile=profile;
 draft.chief=rec.chief?clone(rec.chief):{model:'',effort:''};
